package assignment1;

public class AsciiCodeProgram {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char asc = 'A';
		int value = asc;
		System.out.println("ASCII value of A=" + value);

		char asc1 = 'a';
		int value2 = asc1;
		System.out.println("ASCII value of a=" + value2);

		char asc2 = '0';
		int value3 = asc2;
		System.out.println("ASCII value of 0=" + value3);

		char asc3 = '@';
		int value4 = asc3;
		System.out.println("ASCII value of @=" + value4);
	}

}
